const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lasVegas = ee.Geometry.Point([-115.14, 36.17]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-22';

  // 2. Data Acquisition - Using ERA5 hourly for air temperature
  let tempCol = ee.ImageCollection('ECMWF/ERA5/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(lasVegas)
    .select('temperature_2m'); // Temperature at 2 meters in Kelvin

  const colSize = tempCol.size().getInfo();
  console.log(`ERA5 Images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No ERA5 data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get maximum temperature
  const maxTemp = tempCol.max();

  // 4. Calculation - Extract max temperature value
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lasVegas,
    scale: 27830,
    maxPixels: 1e9
  }).getInfo();

  const maxTempK = result.temperature_2m;

  // 5. Validation & Final Answer
  if (maxTempK === null || maxTempK === undefined || isNaN(maxTempK)) {
    console.log("Temperature calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert Kelvin to Fahrenheit: (K - 273.15) × 9/5 + 32
  const maxTempF = (maxTempK - 273.15) * 9/5 + 32;
  const threshold = 130;

  console.log(`Max Temperature: ${maxTempF.toFixed(2)}°F (${maxTempK.toFixed(2)}K)`);
  console.log(`Threshold: ${threshold}°F`);
  console.log(`Date Range: ${startDate} to ${endDate}`);
  console.log(`Location: Las Vegas, NV`);

  // Sanity check: temperature should be reasonable
  if (maxTempF < -50 || maxTempF > 150) {
    console.log("Temperature out of reasonable range.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (maxTempF > threshold) {
    console.log(`Temperature exceeded ${threshold}°F`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Temperature did not exceed ${threshold}°F`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
